    public static T Read<T>(string path) { using var f = File.OpenRead(Path.IsPathRooted(path) ? path : Path.Combine(Root, path)); using Stream z = path.EndsWith(".gz", StringComparison.Ordinal) ? new GZipStream(f, CompressionMode.Decompress) : f; return JsonSerializer.Deserialize<T>(z, Json)!; }
    public static void Save(string path, object value) { Directory.CreateDirectory(Path.GetDirectoryName(path)!); using var f = new FileStream(path, FileMode.CreateNew); if (path.EndsWith(".gz", StringComparison.Ordinal)) { using var z = new GZipStream(f, CompressionLevel.Optimal); JsonSerializer.Serialize(z, value, Json); } else JsonSerializer.Serialize(f, value, Json); }
    static readonly Process Process = Process.GetCurrentProcess();
    static double Cpu => Process.TotalProcessorTime.TotalSeconds;
    static double entered, prior; static string operation = "";
    static void Begin(string label, double reservation)
    {
        if (label.Length < 1 || label.Any(c => !char.IsAsciiLetterOrDigit(c) && c != '-' && c != '.')) throw new ArgumentException("Simple unique research label required");
        operation = label; entered = 0; Directory.CreateDirectory(Doc); var p = Doc + "/budget.json"; var rows = File.Exists(p) ? Read<JsonElement[]>(p) : Array.Empty<JsonElement>();
        if (rows.Any(r => !r.GetProperty("Closed").GetBoolean())) throw new InvalidOperationException("Inspect unfinished CPU reservation");
        var closed = rows.Select(r => r.GetProperty("Label").GetString()).ToHashSet();
        foreach (var path in Directory.GetFiles(Doc, "reservation-*.json")) if (!closed.Contains(Read<JsonElement>(path).GetProperty("Label").GetString())) throw new InvalidOperationException("Inspect unfinished reservation: " + path);
        prior = rows.Sum(r => r.GetProperty("CpuSeconds").GetDouble()); if (prior + reservation > 1100) throw new InvalidOperationException("Preserve100 CPU-s hard-limit reserve"); Save(Doc + "/reservation-" + label + ".json", new { Label = label, Prior = prior, Reservation = reservation, HardLimit = 1200 });
    }
    static void Guard() { if (prior + Cpu - entered > 1090) throw new InvalidOperationException("CPU reserve stop"); }
    static void End(string reason) { var p = Doc + "/budget.json"; var rows = File.Exists(p) ? Read<JsonElement[]>(p).ToList() : new List<JsonElement>(); rows.Add(JsonSerializer.SerializeToElement(new { Label = operation, CpuSeconds = Cpu - entered, Closed = true, Reason = reason }, Json)); var temporary = p + ".next"; File.WriteAllText(temporary, JsonSerializer.Serialize(rows, Json)); File.Move(temporary, p, true); }
    public static void Main(string[] args)
