    public static void Inspect() { Begin("inspect-v1", 10); var fs = Fixtures(); Save(Doc + "/fixtures.json", fs.Select(f => new { f.Name, f.Source, f.Time, f.Entry, f.Exit, f.Goal, f.Held, State = f.State, PhysicalKey = Efficient147.ExactKey147.State(f.State), Gap = new RacingLineGeometry(StandingWorld144.Frame()).Clearance(f.State.Input.Rider), Reaction = RiderController.ReactionSeconds(f.Spec) })); End("existing full-state fixtures, no new world"); Console.WriteLine(JsonSerializer.Serialize(fs.Select(f => new { f.Name, f.Time, f.Entry, f.Goal, Reference = f.State.Input.Rider.TotalReferenceMeters, Speed = f.State.Input.Rider.Speed * 3.6, Gap = new RacingLineGeometry(StandingWorld144.Frame()).Clearance(f.State.Input.Rider) }), Json)); }
    public static (double Low, double High) Band(string family) => family switch { "A" => (0, 3), "B" => (3, 7), "C" => (7, 12), "U" => (-100, 100), _ => throw new ArgumentException("family A/B/C") };
    public static double Offset(Fixture156 f, Parameters156 p, double reference) { var x = new[] { f.State.Input.Rider.TotalReferenceMeters, f.Entry, f.Entry + (f.Exit - f.Entry) * .5, f.Exit, f.Goal }; if (reference <= x[0]) return p.Offsets[0]; for (int j = 1; j < x.Length; j++) if (reference < x[j]) { var u = Math.Clamp((reference - x[j - 1]) / (x[j] - x[j - 1]), 0, 1); u = u * u * (3 - 2 * u); return p.Offsets[j - 1] + (p.Offsets[j] - p.Offsets[j - 1]) * u; } return p.Offsets[^1]; }
    public static float Drive(Fixture156 f, Parameters156 p, double reference) { var u = (reference - f.Entry) / (f.Exit - f.Entry); return p.Drives[u < 0 ? 0 : u < .25 ? 1 : u < .65 ? 2 : u < 1 ? 3 : 4]; }
    sealed class Experiment(Fixture156 fixture)
    {
        public readonly TrackFrame Frame = StandingWorld144.Frame(); public readonly WorldParameters P = FreeLearningExperiment.Parameters(); public readonly RiderSpec Spec = fixture.Spec; public readonly TrackStateSnapshot Surface = MultiActionExperiment135.Surface(StandingWorld144.Frame()); public readonly Boundary152 Boundary = new(StandingWorld144.Frame());
        public Transition146 Step(State146 s, FreeRacingAction action) { Guard(); double crank = s.CrankOmega; var q = PredictorA153.Predict(s.Input, Spec, Frame, Surface, P, 147, 52.72097f, .2, action, powertrain: new(omega: s.CrankOmega), observeCrank: (_, w) => crank = w, fastBoundary: Boundary, exactInitialWheel: true); var end = q.Points[^1]; var pending = s.Input.Pending.Append(new FreeRacingCommand(s.Input.Time, s.Input.Time + .24, action)).OrderBy(c => c.ActivationAt).ToArray(); var active = pending.Where(c => c.ActivationAt <= end.Time + 1e-10).Select(c => c.Action).LastOrDefault(s.Input.Active); return new(new(new(end.Rider with { Drive = active.Drive }, end.Time, end.Omega, end.Steering, active, pending.Where(c => c.ActivationAt > end.Time + 1e-10).ToArray(), end.Time), crank), q); }
        double Alpha(State146 s, float steering, float drive) { var v = s.Input.Rider with { Drive = drive }; var w = ForecastFork148.Wheel(s.Input.Omega, P.RearWheel); var state = new TwoContactBikeState(s.Input.Steering); return Contact144.Forces(v, Spec, Frame, Surface, P, s.Input.Time, 147, w, state, 0, steeringOverride: steering, inertia: 52.72097f, powertrain: new(omega: s.CrankOmega), releaseAt: .24).NetTorque / 52.72097f; }
        public FreeRacingAction Guide(State146 s, Parameters156 p) { var v = s.Input.Rider; var drive = Drive(fixture, p, v.TotalReferenceMeters); var speed = Math.Max(2, v.Speed); var refAhead = v.TotalReferenceMeters + Math.Max(2, Frame.ReferenceSpeed(v) * p.Preview); var target = Frame.At(refAhead, Offset(fixture, p, refAhead)).Position; var desiredCourse = Math.Atan2(target.Y - v.Position.Y, target.X - v.Position.X); var course = Math.Atan2(v.Velocity.Y, v.Velocity.X); var error = BikeAngles.Wrap(course + v.AngularVelocity * .24 - desiredCourse); var road = Frame.RoadAt(refAhead, Offset(fixture, p, refAhead)); var desiredYaw = (road.IsTurn && double.IsFinite(road.RadiusMeters) ? speed / road.RadiusMeters : 0) - error / p.CourseTime; var desiredAlpha = (desiredYaw - v.AngularVelocity) / p.YawTime; var c = s.Input.Steering; var eps = .5f * MathF.PI / 180; var max = TwoContactBikeParameters.Default.MaximumSteeringRadians; var lo = Math.Max(-max, c - eps); var hi = Math.Min(max, c + eps); var a = Alpha(s, c, drive); var derivative = (Alpha(s, hi, drive) - Alpha(s, lo, drive)) / (hi - lo); var selected = double.IsFinite(derivative) && Math.Abs(derivative) > 1e-8 ? c + (desiredAlpha - a) / derivative : c; return new((float)Math.Clamp(selected + p.SteerBiasDegrees * Math.PI / 180, -max, max), drive); }
        public FreeRacingAction Standard(State146 s, string family)
        {
            var rows = new List<(FreeLearningCandidate C, double Violation)>(); foreach (var action in FreeLearningController.Actions(s.Input, Controller143.Policy, true)) { var q = PredictorA153.Predict(s.Input, Spec, Frame, Surface, P, 147, 52.72097f, .9, action, powertrain: new(omega: s.CrankOmega), fastBoundary: Boundary, exactInitialWheel: true); var old = Objective142.FromPrediction(s.Input, Controller143.Policy, Frame, Surface, q, action); var score = Controller143.Score(old, Policy144.Variant("K1")); var safe = Clearance153.Check(q.Points, Regime153.SafetyHalfMeter); if (!safe.Legal) continue; var end = q.Points[^1].Rider; var band = Band(family); var start = fixture.State.Input.Rider; var u = Math.Clamp((end.TotalReferenceMeters - start.TotalReferenceMeters) / (fixture.Entry + .2 * (fixture.Exit - fixture.Entry) - start.TotalReferenceMeters), 0, 1); var low = start.Road.OffsetMeters + (band.Low - start.Road.OffsetMeters) * u; var high = start.Road.OffsetMeters + (band.High - start.Road.OffsetMeters) * u; var violation = end.TotalReferenceMeters <= fixture.Exit ? Math.Max(0, low - end.Road.OffsetMeters) + Math.Max(0, end.Road.OffsetMeters - high) : 0; rows.Add((old.Candidate with { Score = score.Score, Safety = score.Safety }, violation)); }
            if (rows.Count == 0) throw new InvalidOperationException("T0 no S0.5-safe K1 horizon"); return rows.OrderBy(x => x.Violation > 1e-6 ? 1 : 0).ThenBy(x => x.Violation > 1e-6 ? x.Violation : 0).ThenBy(x => x.C.Safety).ThenBy(x => x.C.Score).ThenBy(x => Math.Abs(x.C.Action.SteeringRadians - s.Input.Active.SteeringRadians)).ThenBy(x => x.C.Action.SteeringRadians).First().C.Action;
        }
    }
    static Attempt156 Rollout(Experiment e, Fixture156 f, string family, string strategy, string label, Parameters156? p, FreeRacingAction[]? tape = null)
    {
        var began = Cpu; var s = f.State; var pts = new List<FreeRacingPoint>(); var actions = new List<FreeRacingAction>(); string reason = "window timeout26s"; bool legal = true, complete = false; double? arrival = null;
        for (int j = 0; j < 130; j++) { try { var action = tape is not null ? tape[Math.Min(j, tape.Length - 1)] : p is null ? (strategy == "UNCONDITIONED" ? Policy144.Choose(s.Input, new(omega: s.CrankOmega), e.Spec, e.Frame, e.Surface, e.P, 147, 52.72097f, "K1").Choice.Action : e.Standard(s, family)) : e.Guide(s, p); var t = e.Step(s, action); actions.Add(action); pts.AddRange(t.Prediction.Points.Skip(pts.Count == 0 ? 0 : 1)); s = t.End; var safety = Clearance153.Check(t.Prediction.Points, Regime153.SafetyHalfMeter); if (!safety.Legal) { legal = false; reason = safety.Reason; break; } if (s.Input.Rider.TotalReferenceMeters >= f.Goal) { complete = true; reason = "complete common geometric section"; break; } } catch (InvalidOperationException ex) { reason = ex.Message; legal = false; break; } }
        if (pts.Count == 0) { var v = f.State.Input.Rider; var gap = e.Boundary.Clearance(v); pts.Add(new(f.Time, v, f.State.Input.Omega, f.State.Input.Steering, gap.Inner, gap.Outer)); }
        for (int j = 1; j < pts.Count; j++) if (pts[j].Rider.TotalReferenceMeters >= f.Goal) { var a = pts[j - 1]; var b = pts[j]; arrival = a.Time + (b.Time - a.Time) * (f.Goal - a.Rider.TotalReferenceMeters) / (b.Rider.TotalReferenceMeters - a.Rider.TotalReferenceMeters); break; }
        var middle = pts.Where(q => q.Rider.TotalReferenceMeters >= f.Entry + .2 * (f.Exit - f.Entry) && q.Rider.TotalReferenceMeters <= f.Entry + .8 * (f.Exit - f.Entry)).ToArray(); double sum = 0, length = 0; for (int j = 1; j < middle.Length; j++) { var ds = Vector2.Distance(middle[j - 1].Rider.Position, middle[j].Rider.Position); sum += ds * (middle[j - 1].Rider.Road.OffsetMeters + middle[j].Rider.Road.OffsetMeters) * .5; length += ds; }
        var mean = length > 0 ? sum / length : s.Input.Rider.Road.OffsetMeters; var band = Band(family); var achieved = length > 1 && mean >= band.Low && mean <= band.High; var total = Clearance153.Check(pts.ToArray(), Regime153.SafetyHalfMeter); return new(label, f.Name, family, strategy, p, actions.ToArray(), s, pts.ToArray(), complete, legal && total.Legal, achieved, reason, arrival, mean, total.MinimumGapMeters, total.SweepLowerBoundMeters, total.MaximumBetaDegrees, Cpu - began);
    }
    static double Fitness(Attempt156 a, Fixture156 f) { var band = Band(a.Family); var violation = Math.Max(0, band.Low - a.MeanOffset) + Math.Max(0, a.MeanOffset - band.High); if (a.Complete && a.Legal && a.FamilyAchieved) return a.Arrival!.Value - f.Time; return 1000 + Math.Max(0, f.Goal - a.End.Input.Rider.TotalReferenceMeters) + 100 * violation + Math.Max(0, .5 - a.Sweep) * 100 + Math.Max(0, a.MaxBeta - 45) * 2; }
    public static void Search(string fixture, string version, double budget)
    {
        var f = Fixtures().Single(x => x.Name == fixture); if (budget < 1 || budget > 250) throw new ArgumentException("bounded1..250CPU-s"); Begin("search-" + fixture + "-" + version, budget + 5); var began = Cpu; try
        {
            var e = new Experiment(f); var log = new List<object>(); foreach (var family in new[] { "A", "B", "C" }) { var row = Rollout(e, f, family, "T0", family + "-T0-" + version, null); Save(Doc + "/attempts/" + f.Name + "-" + row.Label + ".json.gz", row); log.Add(new { row.Label, row.Complete, row.Legal, row.FamilyAchieved, row.MeanOffset, row.Reason, row.Arrival, row.CpuSeconds }); Console.WriteLine($"{fixture} {row.Label}: {row.Reason}, complete={row.Complete} family={row.FamilyAchieved} mean={row.MeanOffset:F2} CPU={Cpu - began:F2}"); }
            foreach (var family in new[] { "A", "B", "C" })
            {
                var target = family == "A" ? 1.5 : family == "B" ? 5 : 9; Attempt156? best = null; int n = 0; var allocation = budget / 3; var familyStart = Cpu; var seeds = new List<Parameters156>(); foreach (var shape in new[] { 0, 1, 2 }) foreach (var gas in new[] { 0f, .31820688f, .6f, 1f }) foreach (var preview in new[] { .44, .8 }) { var offsets = new[] { f.State.Input.Rider.Road.OffsetMeters, shape == 0 ? target : Math.Min(9, target + 2), shape == 2 ? Math.Max(1, target - 2) : target, shape == 1 ? Math.Min(10, target + 2) : target, 5d }; seeds.Add(new(offsets, new[] { 1f, gas, gas, 1f, 1f }, preview)); }
                foreach (var p in seeds) { if (Cpu - familyStart > allocation || Cpu - began > budget) break; var a = Rollout(e, f, family, "T1", family + "-T1-" + version + "-" + (n++).ToString("D4"), p); log.Add(new { a.Label, a.Complete, a.Legal, a.FamilyAchieved, a.MeanOffset, a.Reason, a.Arrival, a.CpuSeconds, Parameters = p }); if (best is null || Fitness(a, f) < Fitness(best, f)) { best = a; Save(Doc + "/attempts/" + f.Name + "-" + a.Label + ".json.gz", a); } }
                if (best is not null && best.Parameters is not null) { for (int sweep = 0; sweep < 3 && Cpu - familyStart < allocation && Cpu - began < budget; sweep++) { bool improved = false; for (int k = 0; k < 12 && Cpu - familyStart < allocation && Cpu - began < budget; k++) foreach (var direction in new[] { -1, 1 }) { var q = best.Parameters!; var offsets = q.Offsets.ToArray(); var drives = q.Drives.ToArray(); var preview = q.Preview; var course = q.CourseTime; var yaw = q.YawTime; var bias = q.SteerBiasDegrees; if (k < 4) offsets[k + 1] = Math.Clamp(offsets[k + 1] + direction * (sweep == 0 ? 2 : 1), .7, 12); else if (k < 9) drives[k - 4] = Math.Clamp(drives[k - 4] + direction * .25f, 0, 1); else if (k == 9) preview = Math.Clamp(preview + direction * .15, .25, 1.2); else if (k == 10) course = Math.Clamp(course + direction * .2, .3, 1.6); else yaw = Math.Clamp(yaw + direction * .15, .2, 1.2); var p = new Parameters156(offsets, drives, preview, course, yaw, bias); var a = Rollout(e, f, family, "T1", family + "-T1-" + version + "-" + (n++).ToString("D4"), p); log.Add(new { a.Label, a.Complete, a.Legal, a.FamilyAchieved, a.MeanOffset, a.Reason, a.Arrival, a.CpuSeconds, Parameters = p }); if (Fitness(a, f) + 1e-6 < Fitness(best, f)) { best = a; improved = true; Save(Doc + "/attempts/" + f.Name + "-" + a.Label + ".json.gz", a); } if (Cpu - familyStart >= allocation || Cpu - began >= budget) break; } if (!improved) break; } }
                Save(Doc + "/best/" + f.Name + "-" + family + "-" + version + ".json.gz", best!); Console.WriteLine($"{fixture} {family} T1 n={n}: {best?.Reason}, complete={best?.Complete} family={best?.FamilyAchieved} legal={best?.Legal} mean={best?.MeanOffset:F2} CPU={Cpu - began:F2}");
            }
            Save(Doc + "/search-" + fixture + "-" + version + ".json", new { Fixture = f, Attempts = log, ElapsedCpu = Cpu - began, Limit = budget, Scope = "offline finite search; family membership from executed forecast XY, no global infeasibility claim" }); End("bounded search complete");
        }
        catch (Exception ex) { End("failed: " + ex.Message); throw; }
    }
    public static void Native(string attemptPath, string label)
    {
        var a = Read<Attempt156>(attemptPath); var f = Fixtures().Single(x => x.Name == a.Fixture); Begin("native-" + label, 20); Snapshot("native-" + label); try
        {
            var prefix = Read<Run144>(f.Source).Riders[0]; State146? observed = null; int index = 0; Decision144 Choose(FreeRacingInput i, CrankClutch144 c, RiderSpec spec, TrackFrame frame, TrackStateSnapshot surface, WorldParameters p, float m, float inertia, string variant) { Guard(); FreeRacingAction action; if (i.Time < f.Time - 1e-8) { action = prefix.Decisions.Single(d => Math.Abs(d.Choice.Time - i.Time) < 1e-7).Choice.Action; } else { observed ??= new(i, c.Omega); if (i.Rider.TotalReferenceMeters >= f.Goal) throw new InvalidOperationException("STUDY156_COMMON_SECTION_REACHED"); if (index >= a.Actions.Length) throw new InvalidOperationException("STUDY156_TAPE_EXHAUSTED"); action = a.Actions[index++]; } return new(new(i.Time, action, FreeActionSafety.SafeInHorizon, false, Array.Empty<FreeLearningCandidate>(), 0, 0), 0); }
            // Prefix is replayed from the same stopped launch, never injected. Old legacy
            // prefixes are allowed only before the study window; S audit below owns PASS.
            Run144 run; using (var w = new NativeWorld156(new(Enabled: true, RequiredLaps: 3, MaximumSeconds: f.Time + 26), safetyHalfMeter: true, safetyFrom: f.Time, stopReference: f.Goal)) run = w.Run(label, "K1", Choose);
            Save(Doc + "/native/" + label + ".json.gz", run); var window = run.Riders[0].Samples.Where(s => s.Input.Time >= f.Time - 1e-8).ToArray(); var points = window.Select(s => new FreeRacingPoint(s.Input.Time, s.Input.Rider, s.Input.Omega, s.Input.Steering, s.Inner, s.Outer)).ToArray(); var safety = Clearance153.Check(points, Regime153.SafetyHalfMeter); var complete = points.Any(p => p.Rider.TotalReferenceMeters >= f.Goal); var exact = observed is not null && Efficient147.ExactKey147.State(observed) == Efficient147.ExactKey147.State(f.State); Save(Doc + "/native/" + label + "-result.json", new { Attempt = attemptPath, Fixture = f, Observed = observed, ExactInitialKey = exact, Complete = complete, Safety = safety, Pass = complete && safety.Legal && exact, run.Outcome, run.EndSeconds, run.Fingerprint, Commands = index, CpuSeconds = Cpu - entered, Scope = "diagnostic witness, not autonomous rider; full native prefix from rest" }); End(run.Outcome); Console.WriteLine($"native {label}: {run.Outcome} complete={complete} S={safety.Legal} exact={exact}");
        }
        catch (Exception ex) { End("failed: " + ex.Message); throw; }
    }
